def main():
    import sys
    input = sys.stdin.read().split('\n')
    input = [list(map(int, list(line.split())) for line in input if line.strip()]

    # Process each test case
    for i in range(len(input)):
        output = []
        for row in input[i]:
            # Calculate the sum of the row
            total = sum(row)
            # Determine the number of non-zero elements
            non_zero = sum(1 for x in row if x != 0)
            if non_zero == 0:
                output.append(0)
            else:
                if total == 0:
                    output.append(0)
                else:
                    # Calculate the output based on the sum
                    output.append(total if total > 0 else 0)

    print('\n'.join(map(str, output)))

if __name__ == "__main__":
    main()
